        body: "황제를 꼭 남자나 윗사람으로 볼 필요는 없어요. 황제는 성별이나 나이보다 기준을 세우고 책임을 지는 역할을 그린 카드라서, 나 자신이 그 자리에 서는 때로도 봐요. 4번(IV) 황제는 회색 돌 왕좌에 정면을 보고 앉아 있고, 팔걸이와 등받이 위에 숫양 머리 장식이 있어요. 오른손에는 윗부분이 고리 모양인 노란 홀(앙크 모양)을, 왼손에는 금색 구슬을 쥐었죠. 길고 흰 수염에 금관을 썼고, 붉은 망토 아래로 갑옷 입은 다리와 쇠 장화가 드러나요. 뒤로는 풀 한 포기 없는 주황빛 바위산이 솟아 있고 하늘도 주황색이에요. 거친 땅에서도 세운 질서, 왕좌에 앉아서도 풀지 않은 긴장이 이 그림의 분위기예요. 흰 수염 덕분에 젊은 패기보다 오래 버티며 다져 온 권위라는 인상이 짙고, 망토 아래 갑옷은 지금도 무언가를 지키는 중이라는 표시로 보기도 해요. 질문이 사람을 묻는다면 아버지나 상사를 떠올릴 수도 있지만, 모임의 규칙을 정하는 친구나 집안 살림의 기준을 잡는 내가 그 자리일 수도 있어요.",
