        body: "정의는 회색 돌기둥 두 개 사이에 앉아 있고, 뒤에는 보랏빛 휘장이 걸려 있어요. 오른손에는 양날 칼을 곧게 세워 들었고, 왼손에는 저울을 들어 아래로 늘어뜨렸죠. 가운데 네모난 보석이 박힌 금관을 쓰고, 붉은 옷 위에 초록 망토를 걸친 채 가슴에 네모난 장식을 달았어요. 얼굴은 정면을 똑바로 보고 있어요. 법원 앞 조각상 가운데에는 천으로 두 눈을 덮은 정의의 여신상이 많아서 이 카드도 그렇게 기억하는 사람이 있지만, 타로의 정의는 두 눈을 뜨고 질문하는 사람을 마주 봐요. 모르는 채 공평한 게 아니라 다 보고 나서 공평하게 정하는 판단이라는 차이가 여기서 생겨요. 옷자락 아래로 흰 신발 한쪽이 살짝 나와 있는 것도 놓치기 쉬운 부분이에요. 이 발을 앉아 있지만 곧 일어설 수 있는 자세로 보고, 판단한 뒤에는 행동이 따라야 한다는 뜻으로 읽는 해석이 있어요. 칼은 분명하게 가르는 판단을, 저울은 양쪽을 같은 무게로 달아 보는 공정함을 맡고요. 칼날이 양쪽에 다 있다는 점을 두고는, 남을 재는 기준이 나에게도 똑같이 돌아온다는 뜻으로 보는 해석이 많아요.",
