        body: "가상의 창업자 이야기로 세 장을 이어 볼게요. 2년 동안 준비한 서비스를 투자자 앞에서 발표했다가 핵심 가정이 틀렸다는 지적을 받은 사람이 '무너진 것, 남아 있는 것, 다시 세울 것' 세 자리에 카드를 놓았어요. 첫 장이 탑, 둘째 장은 석공과 두 사람이 설계도를 두고 이야기하는 펜타클 3, 셋째 장은 여인이 두 항아리로 연못과 땅에 물을 붓는 17번 별이에요. 첫 자리의 탑은 무엇이 부서졌는지를 분명히 하라고 해요. 회사 전체가 아니라 '사람들이 이걸 돈 내고 쓸 것'이라는 꼭대기의 가정 하나가 번개를 맞은 거예요. 벗겨진 금관처럼, 가장 자신 있던 그 생각이 먼저 날아간 셈이죠. 둘째 자리의 펜타클 3은 그 아래에 남은 것을 보여 줘요. 함께 일한 사람들과 쌓은 기술, 서로 맞물려 일하는 방식은 번개와 상관없이 그대로라는 쪽이에요. 셋째 자리의 별은 탑 바로 다음 번호라서, 흔들림 뒤에 조용히 다시 채워지는 회복을 그려요. 큰 계획을 새로 세우기보다 고객 열 명을 직접 만나 무엇이 필요한지 듣는 식으로, 작고 오래가는 일부터 다시 채우라는 쪽으로 풀려요. 다시 투자를 받을 수 있을지는 세 장이 정해 주지 않아요. 무너진 꼭대기와 남은 바닥을 구분하는 일이 이 배치가 건네는 첫 과제예요. 첫 장의 탑이 거꾸로 나왔다면 지적받기 전부터 속으로는 그 가정이 흔들리고 있었다는 쪽으로 보고, 왜 그 의심을 미뤄 왔는지부터 돌아보라고 권했을 거예요.",
